/// Foreground tool-call budget (issue #1786): every running foreground tool
/// call becomes a bounded-unreachability window — user steering and watchdog
/// escalation always reach the agent within a configurable wall-clock budget
/// B (default 10 min), never only when the tool happens to return.
///
/// The budget is a DIFFERENT axis from the bash command timeout: B caps how
/// long the agent loop can be unreachable by steering; the optional command
/// timeout still governs the process when set. The two compose.
///
/// The ladder (Escalation Ladder), armed per foreground call by the loop's
/// `ForegroundCallSupervisor` (see `agent_loop_foreground_budget.dart`, a
/// part of `agent_loop.dart`):
///
/// - rung 1 at B/2 — with no output and steering pending: surface the
///   one-key "background & deliver steering" offer (interactive hosts);
///   `foregroundCallAutoConvert: auto` converts instead of asking
///   (unattended sessions — reversible backgrounding, never a silent kill).
/// - rung 2 at B — force-escalate regardless of output: yield-aware tools
///   (bash over a jobs-capable env) hand the call to `ShellJobRegistry` with
///   output continuity; anything else is aborted with partial output after
///   the cancel grace. Both paths announce in the transcript.
/// - rung 3 — the CLI liveness watchdog's 300s escalation invokes the same
///   supervisor action path (via [ForegroundCallBudgetControls]) instead of
///   printing a second display-only nudge.
///
/// Steering itself is NEVER injected into the blocked call: escalation ends
/// the unreachability window and the queued steering drains through the
/// existing turn-boundary path (`getSteeringMessages`) — no new instruction
/// channel.
///
/// The config is pure data (no IO); yaml parsing follows the strict
/// [StuckToolConfig] pattern — a bad schema throws [ConfigException] at
/// boot. yaml shape (flat `agent:` leaves, named as in the GOAL card):
///
/// ```yaml
/// agent:
///   foregroundCallBudgetSeconds: 600   # B, integer > 0
///   foregroundCallAutoConvert: offer   # offer | auto (default offer)
/// ```
library;

import '../exceptions.dart';
import 'stuck_tool.dart';

/// Default budget B (`agent.foregroundCallBudgetSeconds`): 10 minutes —
/// about 2x the liveness watchdog's escalate point, so rung 1 has room to
/// offer before rung 2 forces.
const defaultForegroundCallBudgetSeconds = 600;

/// Session record type for a budget-ladder action
/// (`CustomRecord.customType`): offer surfaced, auto-convert, force
/// background, or abort-with-partial — every rung lands here, so an
/// escalation can never be silent (issue #1786 AC6).
const foregroundBudgetRecordType = 'foreground_budget';

/// The cancel reason the budget supervisor puts on a call/yield token — a
/// marker, not an error: the tokens' other listeners only check
/// [CancelToken.isCancelled], and bash's unwind path must be able to tell
/// this apart from the stuck supervisor's cancel-retry
/// (`StuckCallFollowUp`) so the budget force escalates to a BACKGROUND
/// hand-back, not a failed retry.
///
/// Deliberately NOT named `StuckCallFollowUp`: bash's
/// `_isSupervisorAbort` classifies that type as cancel-and-retry; any other
/// reason unwinds the job to the background — exactly the budget's
/// reversibility contract.
class ForegroundBudgetFollowUp {
  const ForegroundBudgetFollowUp(this.detail);

  /// Why the budget acted (rung + elapsed), for diagnostics.
  final String detail;
}

/// Which rung of the Escalation Ladder acted (or is about to).
enum ForegroundBudgetRung {
  /// B/2: the one-key offer (interactive) or the config-gated auto-convert
  /// (`foregroundCallAutoConvert: auto`).
  offer,

  /// B: force-escalate — background, or abort-with-partial-output when the
  /// tool cannot be backgrounded.
  force,

  /// The liveness watchdog's 300s escalation invoking the supervisor action
  /// path (rung 3).
  watchdog;

  /// The snake_case label used in session records and HEP frames.
  String get label => switch (this) {
    offer => 'offer',
    force => 'force',
    watchdog => 'watchdog',
  };
}

/// What the supervisor did at a rung (the `action` field of the session
/// record / [ToolCallBudgetEvent]).
enum ForegroundBudgetAction {
  /// The one-key offer was surfaced (interactive hosts).
  offer,

  /// The call was moved to the background (reversible; output continues
  /// into `ShellJobRegistry`).
  background,

  /// No backgrounding was possible: the call was aborted with partial
  /// output captured (last resort, announced).
  abort;

  /// The snake_case label used in session records and HEP frames.
  String get label => switch (this) {
    offer => 'offer',
    background => 'background',
    abort => 'abort',
  };
}

/// The `agent.foregroundCallBudgetSeconds` / `agent.foregroundCallAutoConvert`
/// config (issue #1786). Strict: a bad schema throws at boot; the budget
/// must be a positive integer; `autoConvert` is `offer` (default) or `auto`.
/// Per-tool-kind overrides are a second-tier opt-in and are REJECTED in the
/// core tier (a map where the integer/enum is expected fails validation).
final class ForegroundCallBudgetConfig {
  const ForegroundCallBudgetConfig({
    this.budget = const Duration(seconds: defaultForegroundCallBudgetSeconds),
    this.autoConvert = false,
    this.cancelGrace = const Duration(seconds: defaultStuckCancelGraceSeconds),
  });

  /// The wall-clock budget B. Force-escalation fires at B; the offer rung
  /// at B/2.
  final Duration budget;

  /// `true` = rung 1 auto-converts at B/2 (unattended-friendly, reversible
  /// backgrounding) instead of surfacing the one-key offer.
  final bool autoConvert;

  /// Bounded wait for an escalated call to observe its cancellation before
  /// the supervisor abandons it and captures the partial output — a token-
  /// ignoring zombie cannot stretch the unreachability window past
  /// B + grace. Internal knob (not yaml-exposed); defaults to the stuck
  /// supervisor's grace.
  final Duration cancelGrace;

  /// When rung 1 fires.
  Duration get offerAt => budget ~/ 2;

  /// Parses the two flat `agent:` leaves
  /// (`foregroundCallBudgetSeconds`, `foregroundCallAutoConvert`), applying
  /// the defaults for absent ones.
  static ForegroundCallBudgetConfig fromLeaves({
    Object? budgetSeconds,
    Object? autoConvert,
  }) {
    var budget = const Duration(seconds: defaultForegroundCallBudgetSeconds);
    var auto = false;
    if (budgetSeconds != null) {
      if (budgetSeconds is! int || budgetSeconds <= 0) {
        throw ConfigException(
          '"agent.foregroundCallBudgetSeconds" must be a positive integer, '
          'got: $budgetSeconds',
        );
      }
      budget = Duration(seconds: budgetSeconds);
    }
    if (autoConvert != null) {
      if (autoConvert is! String) {
        throw ConfigException(
          '"agent.foregroundCallAutoConvert" must be a string '
          '(offer | auto)',
        );
      }
      auto = switch (autoConvert) {
        'offer' => false,
        'auto' => true,
        _ => throw ConfigException(
          '"agent.foregroundCallAutoConvert" must be "offer" or "auto", '
          'got: $autoConvert',
        ),
      };
    }
    return ForegroundCallBudgetConfig(budget: budget, autoConvert: auto);
  }
}

/// The deterministic announcement line for a budget action — the REG-1
/// byte-scan target (`[foreground-budget]`): names the rung, the elapsed
/// time, and the steering count, so no escalation is ever silent (AC6).
String foregroundBudgetAnnouncement({
  required ForegroundBudgetRung rung,
  required ForegroundBudgetAction action,
  required String toolName,
  required Duration elapsed,
  required int steeringCount,
  String detail = '',
}) {
  final steering = steeringCount == 1
      ? '1 steering message'
      : '$steeringCount steering messages';
  final suffix = switch (action) {
    ForegroundBudgetAction.offer =>
      ' — accept to move it to the background and deliver $steering now',
    ForegroundBudgetAction.background =>
      'moved to a background job (still running; steering: $steering queued '
          'for the next turn)',
    ForegroundBudgetAction.abort =>
      'aborted with partial output captured (steering: $steering queued for '
          'the next turn)',
  };
  final head =
      '[foreground-budget] rung ${foregroundBudgetRungNumber(rung)}: '
      '$toolName after ${_formatBudgetElapsed(elapsed)}';
  return detail.isEmpty ? '$head $suffix' : '$head — $detail — $suffix';
}

/// The rung number for announcements (1/2/3 per the GOAL card's ladder).
String foregroundBudgetRungNumber(ForegroundBudgetRung rung) => switch (rung) {
  ForegroundBudgetRung.offer => '1',
  ForegroundBudgetRung.force => '2',
  ForegroundBudgetRung.watchdog => '3',
};

/// Human elapsed for budget announcements (`4m05s`).
String _formatBudgetElapsed(Duration duration) {
  final minutes = duration.inMinutes;
  final seconds = duration.inSeconds % 60;
  return '${minutes}m${seconds.toString().padLeft(2, '0')}s';
}

/// The host-created CLI→loop controls for the budget ladder (issue #1786
/// AC2/AC4): the loop registers per-call closures while a budgeted call is
/// in flight; the interactive host invokes them from the one-key stall
/// banner action and from the liveness watchdog's escalate rung.
///
/// Without a controls instance (headless hosts) rung 1 degrades to waiting
/// for rung 2 (or `autoConvert: auto`), and the watchdog keeps its nudge —
/// the bounded-unreachability invariant never depends on this object.
final class ForegroundCallBudgetControls {
  /// Accept closures by in-flight tool call id (parallel calls each
  /// register their own; insertion order = call start order).
  final _acceptors = <String, bool Function()>{};

  /// Offer-request closures by in-flight tool call id (the watchdog's
  /// rung-3 hook escalates the OLDEST eligible call).
  final _requesters = <String, bool Function()>{};

  /// Registers the loop-side closures for one in-flight call (called by the
  /// supervisor when the call starts; [detach] clears them when it ends).
  void attach({
    required String toolCallId,
    required bool Function() requestOffer,
    required bool Function() acceptOffer,
  }) {
    _requesters[toolCallId] = requestOffer;
    _acceptors[toolCallId] = acceptOffer;
  }

  /// Clears the closures of a finished call (no offer may outlive its
  /// call).
  void detach(String toolCallId) {
    _requesters.remove(toolCallId);
    _acceptors.remove(toolCallId);
  }

  /// Watchdog rung 3: fire the offer for the oldest eligible budgeted call.
  /// False = no budgeted call can act (caller keeps the display-only nudge).
  bool requestOffer() {
    for (final requester in _requesters.values) {
      // One call at a time answers the watchdog; stop at the first that
      // surfaced an offer.
      if (requester()) return true;
    }
    return false;
  }

  /// One-key accept: escalate the offered call now. False = that offer is
  /// no longer outstanding (the ladder already acted or the call ended).
  bool acceptOffer(String toolCallId) =>
      _acceptors[toolCallId]?.call() ?? false;
}

/// The ForegroundCallSupervisor (issue #1786): the Escalation Ladder over
/// the wall-clock budget B for every running foreground tool call, plus the
/// [ToolCallBudgetEvent] the hosts persist and surface.
///
/// Split out of `agent_loop.dart` to keep it under the repo's 2800-line
/// size gate. Same library (a `part of`), so the helpers keep their access
/// to the loop's private members.
///
/// The ladder composes with (never replaces) the two existing nets:
/// - steering soft-yield (`steeringNotifications` → the phase yield token):
///   still converts a yield-aware bash call the moment steering arrives;
/// - stuck-call supervision (gh-1054): still owns its derived-threshold
///   cancel/retry/convert stage machine.
///
/// The budget is the UNCONDITIONAL outer bound: it derives nothing from the
/// call's declared timeout (a large explicit timeout defeats the stuck
/// threshold — `stuckThreshold = max(2 × declared, floor)` — which is
/// exactly the 2026-10-22 incident hole this card closes). When the budget
/// fires, it preempts the stuck stage machine: no stuck retry may restart a
/// call the budget has already escalated.
part of 'agent_loop.dart';

/// A budget-ladder action (issue #1786): an offer surfaced, a call moved to
/// the background, or a call aborted with partial output — every rung lands
/// here, session-visible, so no escalation is ever silent (AC6).
final class ToolCallBudgetEvent extends AgentEvent {
  const ToolCallBudgetEvent({
    required this.toolCallId,
    required this.toolName,
    required this.args,
    required this.rung,
    required this.action,
    required this.elapsed,
    required this.steeringCount,
    this.detail = '',
    required this.timestamp,
  });

  /// The [ToolCall.id] the ladder acted on.
  final String toolCallId;

  /// The tool's name.
  final String toolName;

  /// The parsed tool call arguments.
  final Map<String, dynamic> args;

  /// Which rung fired (1 = offer/auto, 2 = force, 3 = watchdog).
  final ForegroundBudgetRung rung;

  /// What the supervisor did (or is offering to do).
  final ForegroundBudgetAction action;

  /// How long the call had run when the rung fired.
  final Duration elapsed;

  /// Steering messages queued at fire time (the count the escalation
  /// delivers into the next turn through the existing boundary drain).
  final int steeringCount;

  /// The deterministic announcement line (the REG-1 byte-scan target).
  final String detail;

  /// When the rung fired.
  final DateTime timestamp;
}

/// Call-scoped state of the budget ladder — spans every stuck-supervision
/// attempt of the call (B counts from CALL start, not attempt start).
/// Grouped into one object so the timer callbacks stay top-level functions
/// under the CRAP ratchet (12.0).
final class _BudgetClock {
  _BudgetClock({
    required this.toolCall,
    required this.budget,
    required this.pendingSteeringCount,
  }) : stopwatch = Stopwatch()..start();

  final ToolCall toolCall;
  final Stopwatch stopwatch;
  final ForegroundCallBudgetConfig budget;
  final int Function()? pendingSteeringCount;

  Timer? offerTimer;
  Timer? forceTimer;
  Timer? graceTimer;

  /// Cleared when the call is over: the timers must then become no-ops
  /// (no rung may outlive the call).
  bool alive = true;

  /// The ladder acted (offer accepted, auto-convert, or force) — one-shot.
  bool ladderFired = false;

  /// The one-key offer is on the table (interactive hosts decide).
  bool offerOutstanding = false;

  /// Fire-time snapshots for the outcome announcement.
  late ForegroundBudgetRung escalationRung;
  late Duration escalationElapsed;
  int escalationSteeringCount = 0;

  /// Output seen so far (the rung-1 "no output" condition, E8) and the
  /// last partial text (the abort path's partial-output capture).
  int outputBytes = 0;
  String partialText = '';

  /// The CURRENT attempt's plumbing, registered by [_supervisedAttempt]:
  /// a fire between attempts cancels stale tokens harmlessly; the grace
  /// gate opens the current attempt's bounded wait.
  CancelTokenSource? attemptCallSource;
  CancelTokenSource? attemptYieldSource;
  _AttemptClock? attemptClock;
  void Function(AgentEvent event)? enqueue;

  void disarm() {
    offerTimer?.cancel();
    forceTimer?.cancel();
    graceTimer?.cancel();
    alive = false;
  }
}

/// Whether the budget supervises a tool call: everything EXCEPT the same
/// human-blocking / self-supervised class the stuck supervisor excludes by
/// default — `ask`/`request_secret` block on a human by design (a budget
/// force would abort a deliberation), `task` runs whole subagents whose
/// own machinery owns long runs.
bool _budgetAppliesTo(String toolName) =>
    !StuckToolConfig.defaultStuckExcludedTools.contains(toolName);

/// Arms the ladder's two timers for one call: the rung-1 offer deadline at
/// B/2 and the rung-2 force deadline at B. Timers are no-ops once the call
/// ends ([_BudgetClock.disarm]), so short calls keep byte-identical legacy
/// behavior (AC7).
void _armBudgetTimers(_BudgetClock clock) {
  clock.offerTimer = Timer(clock.budget.offerAt, () {
    _onBudgetOfferDeadline(clock);
  });
  clock.forceTimer = Timer(clock.budget.budget, () {
    // Rung 2 fires at B regardless of output (UT-1); an outstanding
    // unaccepted offer force-escalates too.
    _escalateBudgetNow(clock, rung: ForegroundBudgetRung.force);
  });
}

/// The rung-1 deadline: the offer (or the config-gated auto-convert) fires
/// only when the call is silent AND steering is pending (UT-1) — output
/// activity resets the condition (E8) and an empty steering FIFO skips the
/// rung (E2).
void _onBudgetOfferDeadline(_BudgetClock clock) {
  if (!_budgetOfferEligible(clock)) return;
  if (clock.budget.autoConvert) {
    // Unattended sessions: background (reversible) instead of asking —
    // never a silent kill (the outcome event lands when the stage
    // advances, mirroring the stuck supervisor's deferred records).
    _escalateBudgetNow(clock, rung: ForegroundBudgetRung.offer);
    return;
  }
  _surfaceBudgetOffer(clock, ForegroundBudgetRung.offer);
}

/// Whether a rung-1 offer may fire for [clock] right now.
bool _budgetOfferEligible(_BudgetClock clock) {
  if (!clock.alive || clock.ladderFired || clock.offerOutstanding) {
    return false;
  }
  if (clock.outputBytes > 0) return false;
  return (clock.pendingSteeringCount?.call() ?? 0) > 0;
}

/// Surfaces the one-key "background & deliver steering" offer (rung 1, or
/// rung 3 when the watchdog's escalate invoked it). Purely advisory: the
/// call keeps running until the user accepts or rung 2 fires.
void _surfaceBudgetOffer(_BudgetClock clock, ForegroundBudgetRung rung) {
  clock.offerOutstanding = true;
  final steering = clock.pendingSteeringCount?.call() ?? 0;
  final announcement = foregroundBudgetAnnouncement(
    rung: rung,
    action: ForegroundBudgetAction.offer,
    toolName: clock.toolCall.name,
    elapsed: clock.stopwatch.elapsed,
    steeringCount: steering,
  );
  clock.enqueue?.call(
    ToolCallBudgetEvent(
      toolCallId: clock.toolCall.id,
      toolName: clock.toolCall.name,
      args: clock.toolCall.arguments,
      rung: rung,
      action: ForegroundBudgetAction.offer,
      elapsed: clock.stopwatch.elapsed,
      steeringCount: steering,
      detail: announcement,
      timestamp: DateTime.now(),
    ),
  );
}

/// The watchdog's rung-3 hook (AC4): fire the offer NOW instead of letting
/// the tracker print a second display-only nudge. Returns false when the
/// ladder cannot act (no in-flight silent call / steering pending / already
/// acted) — the caller keeps its legacy nudge in that case.
bool _requestBudgetOffer(_BudgetClock clock) {
  if (!_budgetOfferEligible(clock)) return false;
  _surfaceBudgetOffer(clock, ForegroundBudgetRung.watchdog);
  return true;
}

/// The one-key accept (rung 1): escalate immediately — background if the
/// tool hands back, else abort-with-partial after the grace. False when the
/// offer is gone (the ladder already acted or the call ended).
bool _acceptBudgetOffer(_BudgetClock clock) {
  if (!clock.alive || clock.ladderFired || !clock.offerOutstanding) {
    return false;
  }
  _escalateBudgetNow(clock, rung: ForegroundBudgetRung.offer);
  return true;
}

/// Escalates NOW: cancels the current attempt's yield token first (a
/// jobs-capable bash hands the call to `ShellJobRegistry` untouched —
/// reversible) and then the call token (token-obeying tools abort), and
/// opens the cancel grace so even a token-ignoring zombie cannot stretch
/// the unreachability window past B + grace (E6). The outcome event waits
/// for [_finalizeBudgetEscalation], which only announces what ACTUALLY
/// happened (a call that completes inside the grace never leaves a forced
/// record behind — mirroring the stuck supervisor's deferred records).
void _escalateBudgetNow(
  _BudgetClock clock, {
  required ForegroundBudgetRung rung,
}) {
  if (!clock.alive || clock.ladderFired) return;
  clock.ladderFired = true;
  clock.offerOutstanding = false;
  clock.escalationRung = rung;
  clock.escalationElapsed = clock.stopwatch.elapsed;
  clock.escalationSteeringCount = clock.pendingSteeringCount?.call() ?? 0;
  final reason = ForegroundBudgetFollowUp(
    'foreground budget rung ${rung.label} at '
    '${_formatElapsed(clock.escalationElapsed)}',
  );
  clock.attemptYieldSource?.cancel(reason);
  clock.attemptCallSource?.cancel(reason);
  final attempt = clock.attemptClock;
  if (attempt != null && !attempt.graceGate.isCompleted) {
    if (clock.budget.cancelGrace > Duration.zero) {
      clock.graceTimer = Timer(clock.budget.cancelGrace, () {
        // The stuck supervisor's grace timer may share this gate (both
        // ladders can be armed on one call): the guard keeps a late
        // orphan timer from completing a settled Completer.
        if (!attempt.graceGate.isCompleted) attempt.graceGate.complete();
      });
    } else {
      attempt.graceGate.complete();
    }
  }
}

/// Classifies the post-escalation attempt and lands the outcome: a hand-back
/// result (the call was backgrounded) is marked and returned; a genuine
/// completion inside the grace is marked without a forced record; anything
/// else is the abort path — a session-visible budget event plus an error
/// result carrying the announcement and the captured partial output.
Future<ToolExecutionResult> _finalizeBudgetEscalation({
  required _BudgetClock clock,
  required ToolCall toolCall,
  required _SupervisedAttempt outcome,
  required AgentEventSink emit,
}) async {
  final announcement = foregroundBudgetAnnouncement(
    rung: clock.escalationRung,
    action: ForegroundBudgetAction.abort,
    toolName: toolCall.name,
    elapsed: clock.escalationElapsed,
    steeringCount: clock.escalationSteeringCount,
  );
  if (outcome.error == null && !outcome.hung) {
    final result = outcome.result!;
    if (_isBackgroundHandback(result)) {
      final line = foregroundBudgetAnnouncement(
        rung: clock.escalationRung,
        action: ForegroundBudgetAction.background,
        toolName: toolCall.name,
        elapsed: clock.escalationElapsed,
        steeringCount: clock.escalationSteeringCount,
      );
      await emit(
        _budgetRecord(clock, toolCall, ForegroundBudgetAction.background, line),
      );
      return _prefixMarks([line], result);
    }
    // The call finished its own work inside the grace: nothing was forced,
    // so no forced record (only the truthful mark on the result).
    return _prefixMarks([
      '$announcement — the call completed as the budget fired.',
    ], result);
  }
  final partial = clock.partialText.isEmpty
      ? ''
      : '\n\nPartial output so far:\n${clock.partialText}';
  // A hung outcome means the call ignored both tokens (E6): the zombie
  // handle is named in the announcement, the partial output is captured.
  final line = outcome.hung
      ? foregroundBudgetAnnouncement(
          rung: clock.escalationRung,
          action: ForegroundBudgetAction.abort,
          toolName: toolCall.name,
          elapsed: clock.escalationElapsed,
          steeringCount: clock.escalationSteeringCount,
          detail: 'the call ignored cancellation',
        )
      : announcement;
  await emit(
    _budgetRecord(clock, toolCall, ForegroundBudgetAction.abort, line),
  );
  throw StateError('$line$partial');
}

/// The outcome event for a forced budget action (the session-record feed).
ToolCallBudgetEvent _budgetRecord(
  _BudgetClock clock,
  ToolCall toolCall,
  ForegroundBudgetAction action,
  String detail,
) => ToolCallBudgetEvent(
  toolCallId: toolCall.id,
  toolName: toolCall.name,
  args: toolCall.arguments,
  rung: clock.escalationRung,
  action: action,
  elapsed: clock.escalationElapsed,
  steeringCount: clock.escalationSteeringCount,
  detail: detail,
  timestamp: DateTime.now(),
);

