    return _SupervisedAttempt.completed(
      completedResult!,
      afterStuck: clock.stuckFired,
    );
  }
  return _SupervisedAttempt.hung(
    clock.stopwatch.elapsed,
    clock.outputBytes,
    clock.partialText,
  );
}

