import assert from 'node:assert/strict';
import { test } from 'node:test';
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import {
  WIRE_VERSION,
  WireProtocolError,
  WireVersionError,
  abortCommand,
  acceptWelcome,
  approvalResponseCommand,
  askResponseCommand,
  decodeEvent,
  encodeUnknownEvent,
  frameLine,
